WITH exploded AS (SELECT id, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(tier_limits) x AS element) SELECT id, element, DENSE_RANK() OVER w_grp AS element_dense_rank, CUME_DIST() OVER w_recent AS element_cume_dist, CUME_DIST() OVER w_hist AS element_cume_dist_2, CUME_DIST() OVER (ORDER BY element NULLS FIRST) AS element_cume_dist_3, CUME_DIST() OVER w_hist AS element_cume_dist_4 FROM exploded WINDOW w_grp AS (ORDER BY element), w_recent AS (ORDER BY element DESC NULLS LAST), w_hist AS (ORDER BY element DESC)
